function urlEncode(str){return encodeURIComponent(str);}function urlDecode(str){return decodeURIComponent(str.replace(/\+/g, " "));} const URL_ENCODED_RE = /%[0-9A-Fa-f]{2}/;function executeUrlAuto(){const raw = document.getElementById("url-input").value;const out = document.getElementById("url-result");if (!raw){GAMA.say("idle");out.textContent = "";return;}if (URL_ENCODED_RE.test(raw)){try{out.textContent = urlDecode(raw);GAMA.say("success");}catch (e){GAMA.say("error");out.textContent = "// not valid percent-encoding";}}else{out.textContent = urlEncode(raw);GAMA.say("success");}}const executeUrlAutoDebounced = GAMA.debounce(executeUrlAuto, 300);